import{_ as a,a as r,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"OSS：对象身份、权限与版本机制","description":"从桶与对象名称接续到版本、条件请求、校验与签名。","frontmatter":{"title":"OSS：对象身份、权限与版本机制","description":"从桶与对象名称接续到版本、条件请求、校验与签名。","showdocs":{"topics":[{"id":"oss","title":"阿里云 OSS","link":"/topics/oss/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"OSS 原生对象存储理论与 CLI 阅读","summary":"从桶与对象名称接续到版本、条件请求、校验与签名。","status":"active","related":[{"title":"OSS 实践：完整原生 SDK CLI 阅读项目","link":"/middleware/object-storage/oss/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"OSS：生命周期、恢复与故障推演","link":"/middleware/object-storage/oss/recovery","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":{"text":"OSS 实践：完整原生 SDK CLI 阅读项目","link":"/middleware/object-storage/oss/plus/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"OSS 实践：完整原生 SDK CLI 阅读项目","link":"/middleware/object-storage/oss/plus/practice/application"}},"headers":[],"relativePath":"middleware/object-storage/oss/object-model.md","filePath":"middleware/object-storage/oss/object-model.md"}'),s={name:"middleware/object-storage/oss/object-model.md"};function c(l,e,n,d,p,i){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="oss-对象身份、权限与版本机制" tabindex="-1">OSS：对象身份、权限与版本机制 <a class="header-anchor" href="#oss-对象身份、权限与版本机制" aria-label="Permalink to &quot;OSS：对象身份、权限与版本机制&quot;">​</a></h1><h2 id="part-1" tabindex="-1">对象模型、地域与 RAM 权限 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;对象模型、地域与 RAM 权限 {#part-1}&quot;">​</a></h2><h3 id="part-1-scope" tabindex="-1">阅读范围与版本 <a class="header-anchor" href="#part-1-scope" aria-label="Permalink to &quot;阅读范围与版本 {#part-1-scope}&quot;">​</a></h3><p>阿里云 OSS 是按对象键访问内容的托管对象存储。本文面向普通 Bucket，使用 Python 3.10+ 与 <code>oss2&gt;=2.19,&lt;3</code> 的 Python SDK V1 合同；它与导入 <code>alibabacloud_oss_v2</code> 的 SDK V2 是不同项目，不能混用构造器和返回类型。依赖范围是教学声明，不是已经解析的锁文件，也不代表最新版本。2026-10-17 只核对官方文档与源码；本轮没有安装 SDK、连接账号、执行示例或创建资源。</p><p>学习顺序是本篇、<a href="#part-2">机制</a>、<a href="/middleware/object-storage/oss/plus/practice/application">完整 CLI</a>、<a href="/middleware/object-storage/oss/recovery#part-1">维护</a>、<a href="/middleware/object-storage/oss/recovery#part-2">复习</a>。读者应已理解 HTTP 状态码、Python 文件流与环境变量；没有云账号也能完成所有推演题。将后文自行运行命令视为可选实验，不是本站构建步骤。</p><h3 id="part-1-model" tabindex="-1">Bucket、对象键与地域 <a class="header-anchor" href="#part-1-model" aria-label="Permalink to &quot;Bucket、对象键与地域 {#part-1-model}&quot;">​</a></h3><p>OSS Bucket 的名称、地域和 Endpoint 共同确定请求目标；对象键是完整字符串，<code>reports/2026/a.txt</code> 中的斜杠只是命名约定。列举前缀不能替代目录权限，更没有本地文件系统的原子目录重命名。搬移一个前缀通常是逐对象复制并删除，过程中应允许两个位置同时存在，不能把一次列表当作事务快照。</p><p>应用数据库应记录 Bucket、key、版本 ID、业务摘要与状态，而不是只存一个会过期的下载链接。地域选错可能导致重定向或签名错误；内网 Endpoint 的可达性与互联网域名不同。示例使用 HTTPS 普通地域 Endpoint，不替读者配置 CDN、跨地域复制或自定义域名。</p><h3 id="part-1-credentials" tabindex="-1">RAM 与凭据链 <a class="header-anchor" href="#part-1-credentials" aria-label="Permalink to &quot;RAM 与凭据链 {#part-1-credentials}&quot;">​</a></h3><p>OSS RAM 最小权限应拆成桶级列举 <code>oss:ListObjects</code> 与前缀内对象的 <code>oss:GetObject</code>、<code>oss:PutObject</code>；按版本读取、永久删除还需核对 <code>oss:GetObjectVersion</code>、<code>oss:DeleteObjectVersion</code> 等操作。资源范围绑定实验桶及 <code>theory-lab/your-session/*</code>，列举权限结合前缀条件限制；不要给应用 <code>AliyunOSSFullAccess</code>。若启用 KMS，还要独立审查密钥授权，OSS 权限不自动包含 KMS 使用权。</p><p>示例的凭据链是显式 <code>EnvironmentVariableCredentialsProvider</code>，读取 <code>OSS_ACCESS_KEY_ID</code>、<code>OSS_ACCESS_KEY_SECRET</code> 及可选 <code>OSS_SESSION_TOKEN</code>，再由 <code>ProviderAuthV4</code> 签名；它没有自动选择角色的逻辑，也不负责刷新一组导出的 STS 临时值。生产优先工作负载角色与可刷新提供器，示例只演示输入边界。环境文件仅列变量名，不能把真实密钥、临时 token 或签名 URL 提交到仓库。<a href="https://www.alibabacloud.com/help/en/oss/developer-reference/simple-upload-2" target="_blank" rel="noopener noreferrer">官方 V1 上传示例</a>展示这一 V4 构造方式。</p><h3 id="part-1-commands" tabindex="-1">请求、成本与第一道练习 <a class="header-anchor" href="#part-1-commands" aria-label="Permalink to &quot;请求、成本与第一道练习 {#part-1-commands}&quot;">​</a></h3><p>OSS CLI 在本系列中指仓库 <code>examples/oss/object_cli.py</code>，不是 <code>ossutil</code>。它只支持 list、put、get、sign、delete，不创建 Bucket，不修改权限；put 每次产生随机键且限制 1 MiB，delete 必须提供版本 ID。先阅读 <code>python object_cli.py --help</code> 的参数合同即可理解入口，本轮连 help 也未执行。</p><p>请求费、存储费、外网下载流量、旧版本容量、归档取回和未完成分片都会构成成本。小文件限制不能限制 list 页数或下载流量，前缀也不是服务端授权；必须结合真实 RAM、预算及人工清理记录。练习：只允许上传图片为何还要限制列举？答案是列举可暴露对象名和业务标识；若业务根本不需要列举，就不要授予此动作。</p><h3 id="part-1-sources" tabindex="-1">官方依据 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;官方依据 {#part-1-sources}&quot;">​</a></h3><p>核对来源：<a href="https://www.alibabacloud.com/help/en/oss/user-guide/oss-sdk-quick-start" target="_blank" rel="noopener noreferrer">OSS SDK 指南</a>、<a href="https://github.com/aliyun/aliyun-oss-python-sdk" target="_blank" rel="noopener noreferrer">SDK V1 源码</a>、<a href="https://www.alibabacloud.com/help/zh/oss/developer-reference/putobject" target="_blank" rel="noopener noreferrer">PutObject 中文 API</a>。后续每篇对机制分别给出 API 来源；兼容其他对象存储的工具经验不能代替这些合同。</p><h2 id="part-2" tabindex="-1">版本、防覆盖、CRC64 与分片 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;版本、防覆盖、CRC64 与分片 {#part-2}&quot;">​</a></h2><h3 id="part-2-versions" tabindex="-1">版本 ID 与删除标记 <a class="header-anchor" href="#part-2-versions" aria-label="Permalink to &quot;版本 ID 与删除标记 {#part-2-versions}&quot;">​</a></h3><p>前置是 <a href="#part-1-model">Bucket 模型</a>。OSS 版本控制启用后，同键写入产生独立版本，应用必须保存 <code>x-oss-version-id</code>；省略 versionId 的读取取当前版本。普通删除通常添加删除标记，让当前对象表现为不存在，历史内容仍可按版本读取且继续计费。指定版本删除则永久删除该版本；删除标记也有自身 ID，删除它可能重新暴露早先内容。因此“删除成功”“用户看不见”“数据永久销毁”是三个不同结论。<a href="https://www.alibabacloud.com/help/en/oss/user-guide/manage-objects-in-a-versioning-enabled-bucket" target="_blank" rel="noopener noreferrer">官方版本管理指南</a>说明了这些操作。</p><p>暂停版本控制不等于回到从未开启状态，null 版本及既有历史版本仍需单独分析。版本控制也不是备份：有权限的主体和生命周期仍能删除历史版本。恢复前列明 key、各版本 ID、时间及删除标记，先按精确版本下载核对摘要，再决定复制旧版本为新当前版本，避免凭“最后修改时间”猜目标。</p><h3 id="part-2-concurrency" tabindex="-1">防覆盖与并发边界 <a class="header-anchor" href="#part-2-concurrency" aria-label="Permalink to &quot;防覆盖与并发边界 {#part-2-concurrency}&quot;">​</a></h3><p>OSS 防覆盖头 <code>x-oss-forbid-overwrite=true</code> 可以在适用的非版本桶阻止同名对象覆盖，冲突返回 409；但在版本已启用或已暂停的目标桶中不生效。它不是 S3 <code>IfNoneMatch</code> 的通用替代，更不是基于 ETag 的任意写入 CAS。先 HEAD 再 PUT 存在竞争窗口；后到写入仍能改变当前版本。此限制见 <a href="https://www.alibabacloud.com/help/en/oss/developer-reference/putobject" target="_blank" rel="noopener noreferrer">PutObject 英文 API</a>。</p><p>条件 GET 的 If-Match 约束所读取的对象，复制的 <code>x-oss-copy-source-if-match</code> 约束源对象；不能从这些参数推导出目标写入的比较并交换。应用若要发布唯一业务结果，可先上传 UUID 不变对象，再让数据库唯一键或事务更新“当前对象版本”引用。示例随机键只降低碰撞概率，不声称提供业务幂等性；重试生成另一个 UUID 会留下两份对象。<a href="https://www.alibabacloud.com/help/en/oss/developer-reference/copyobject" target="_blank" rel="noopener noreferrer">CopyObject 合同</a>也区分源条件和目标版本。</p><h3 id="part-2-checksum" tabindex="-1">CRC64、摘要与读取完整性 <a class="header-anchor" href="#part-2-checksum" aria-label="Permalink to &quot;CRC64、摘要与读取完整性 {#part-2-checksum}&quot;">​</a></h3><p>OSS CRC64 用于检查传输完整性，V1 <code>enable_crc=True</code> 打开 SDK 校验；上传和完整读取的校验路径与范围读取不同。CRC64 是检错码，不是密码学内容指纹，也不证明上传者身份。MD5、ETag 和 CRC64 不能互换，特别是分片对象不能默认把 ETag 当全文 MD5。业务去重另存 SHA-256 并记录大小，下载完整内容后再比较；失败文件应留作诊断或删除，不能发布给消费者。<a href="https://www.alibabacloud.com/help/en/oss/developer-reference/data-verification-4" target="_blank" rel="noopener noreferrer">官方数据校验</a>是这里的 SDK 依据。</p><h3 id="part-2-signing" tabindex="-1">V4 签名与短期授权 <a class="header-anchor" href="#part-2-signing" aria-label="Permalink to &quot;V4 签名与短期授权 {#part-2-signing}&quot;">​</a></h3><p>OSS V4 签名把请求方法、资源、地域和参与签名的请求字段绑定到凭据。<code>sign_url(&#39;GET&#39;, key, 300)</code> 生成五分钟读取能力，不会检查对象已存在或接收者是否可信。调用者拿到 URL 即可在有效期内使用；临时凭据先失效时 URL 也会提前失效。URL 中的路径编码、查询参数、Host 和签名头被代理更改都可能导致验签失败。不要签完后再拼接业务参数，不要把 URL 写入常规日志。</p><p>私有桶也会允许持有有效签名的匿名接收者完成被授权请求。业务下载接口仍需校验用户、对象归属及过期时间；撤销一个分享链接通常需要更上层的访问网关，而不是期待对象 ACL 自动识别接收人。</p><h3 id="part-2-multipart" tabindex="-1">分片上传与提交 <a class="header-anchor" href="#part-2-multipart" aria-label="Permalink to &quot;分片上传与提交 {#part-2-multipart}&quot;">​</a></h3><p>OSS 分片上传经历初始化 uploadId、上传带 partNumber 的分片、提交有序 PartInfo 列表三个阶段。只完成部分分片不会产生完整可读对象，却会保留计费碎片。失败重试必须保留同一个 uploadId、分片大小与内容，提交时不能把不同文件的分片混用；放弃任务要执行 AbortMultipartUpload 或配置碎片生命周期。<a href="https://www.alibabacloud.com/help/en/oss/developer-reference/use-oss-python-sdk-to-multipart-upload" target="_blank" rel="noopener noreferrer">SDK V1 分片说明</a>提供原生接口。</p><p>本系列 CLI 使用小对象普通 PUT，未实现分片调度。练习：进程在提交成功响应前断线，是否立即重新初始化？答案：先以业务记录、对象版本与摘要核对结果；“未收到成功”不等于“服务端未提交”。若重试策略无法判断结果，应让不变对象与数据库引用共同消除误发布风险。</p>',31)])])}const b=a(s,[["render",c]]);export{u as __pageData,b as default};
